return {"stack": str(ui.call("dialog_stack")), "content_visible": (content != null and content.visible), "content_context": (str(content.context()) if content != null else "")}

var menu = get_node("/root/Spine/Ui/UiRoot/MenuGroup/menu")
var btns = menu.get_node("Sidebar/Buttons").get_children()
var matches = btns.filter(func(b): return b.find_children("*", "Label", true, false).map(func(l): return l.text).has("Settings"))
var b = matches[0]
var c = (b as Control).get_global_rect().get_center()
return {"x": int(c.x), "y": int(c.y)}

var dlg = get_node("/root/Spine/Ui/UiRoot/DialogLayer/settings")
var rail = dlg.get("_rail")
var hits = rail.find_children("*", "Button", true, false).filter(func(b): return b.find_children("*", "Label", true, false).map(func(l): return str(l.text)).has("Game Data"))
var b = hits[0] as Control
var c = b.get_global_rect().get_center()
return {"x": int(c.x), "y": int(c.y)}

var dlg = get_node("/root/Spine/Ui/UiRoot/DialogLayer/settings")
var rows = dlg._table_host.get_children().map(func(b):
	var texts = b.find_children("*", "Label", true, false).map(func(l): return l.text)
	var label = b.text if not b.text.is_empty() else (texts[texts.size() - 1] if texts.size() > 0 else "")
	var c = (b as Control).get_global_rect().get_center()
	return {"text": label, "visible": b.visible, "disabled": b.disabled, "x": int(c.x), "y": int(c.y)})
return {"count": dlg._table_host.get_children().size(), "actions": rows}

Input.flush_buffered_events()
var ui_root = get_node("/root/Spine/Ui/UiRoot")
var prompts = ui_root.get_node("OverlayLayer").get_children().filter(func(n): return n.find_children("*", "Button", true, false).size() > 0)
var pp = prompts[0]
var texts = pp.find_children("*", "RichTextLabel", true, false).map(func(l): return str(l.get("text")))
var btns = pp.find_children("*", "Button", true, false)
return {"prompt": texts, "buttons": btns.map(func(b): return b.text)}

var ui = get_node("/root/MindUi")
var abs_path = ProjectSettings.globalize_path("user://eval-data-export.zip")
var export_ok = ui.call("data_export", abs_path)
return {"export_ok": export_ok, "path": abs_path, "exists": FileAccess.file_exists(abs_path), "size": (FileAccess.open(abs_path, FileAccess.READ).get_length() if FileAccess.file_exists(abs_path) else -1)}

